[Labels](https://cloud.google.com/workstations/docs/label-resources) that
are applied to the workstation and that are also propagated to the
underlying Compute Engine resources.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Time when this workstation was created.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Time when this workstation was most recently updated.

=item * C<< $msg->start_time() >> / C<< $msg->start_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Time when this workstation was most recently successfully
started, regardless of the workstation's initial state.

=item * C<< $msg->delete_time() >> / C<< $msg->delete_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Time when this workstation was soft-deleted.

=item * C<< $msg->etag() >> / C<< $msg->etag($value) >>

Type: C<String>

Optional. Checksum computed by the server. May be sent on update and delete
requests to make sure that the client has an up-to-date value before
proceeding.

=item * C<< $msg->persistent_directories() >> / C<< $msg->persistent_directories($value) >>

Type: C<Message> (L<Google::Cloud::Workstations::V1::Workstations::Workstation::WorkstationPersistentDirectory>)

Optional. Directories to persist across workstation sessions.

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Workstations::V1::Workstation::State>)

Output only. Current state of the workstation.

=item * C<< $msg->host() >> / C<< $msg->host($value) >>

Type: C<String>

Output only. Host to which clients can send HTTPS traffic that will be
received by the workstation. Authorized traffic will be received to the
workstation as HTTP on port 80. To send traffic to a different port,
clients may prefix the host with the destination port in the format
`{port}-{host}`.

=item * C<< $msg->env() >> / C<< $msg->env($value) >>

Type: C<Message> (L<Google::Cloud::Workstations::V1::Workstations::Workstation::EnvEntry>)

Optional. Environment variables passed to the workstation container's
entrypoint.

=item * C<< $msg->kms_key() >> / C<< $msg->kms_key($value) >>

Type: C<String>

Output only. The name of the Google Cloud KMS encryption key used to
encrypt this workstation. The KMS key can only be configured in the
WorkstationConfig. The expected format is
`projects/*/locations/*/keyRings/*/cryptoKeys/*`.

=item * C<< $msg->source_workstation() >> / C<< $msg->source_workstation($value) >>

Type: C<String>

Optional. The source workstation from which this workstation's persistent
directories were cloned on creation.

=item * C<< $msg->runtime_host() >> / C<< $msg->runtime_host($value) >>

Type: C<Message> (L<Google::Cloud::Workstations::V1::Workstations::Workstation::RuntimeHost>)

Optional. Output only. Runtime host for the workstation when in
STATE_RUNNING.

